16	  test("converts single function tool", async () => {
17	    const tools: ChatCompletionCreateParams["tools"] = [
18	      {
19	        type: "function",
20	        function: {
21	          name: "readFile",
22	          description: "Read a file from disk",
23	          parameters: {
24	            type: "object",
25	            properties: {
26	              filepath: {
27	                type: "string",
28	                description: "Path to the file",
29	              },
30	            },
31	            required: ["filepath"],
32	          },
33	        },
34	      },
35	    ];
36	
37	    const result = await convertToolsToVercelFormat(tools);
38	
39	    expect(result).toBeDefined();
40	    expect(result).toHaveProperty("readFile");
41	    expect(result?.readFile).toHaveProperty(
42	      "description",
43	      "Read a file from disk",
44	    );
45	    expect(result?.readFile).toHaveProperty("parameters");
46	    // Check that parameters were wrapped with aiJsonSchema
47	    expect(result?.readFile.parameters).toBeDefined();
