import type { ChatCompletionChunk } from "openai/resources/index";
import { chatChunk, chatChunkFromDelta, usageChatChunk } from "./util.js";

export type VercelStreamPart =
  | { type: "text-delta"; id: string; text: string }
  | { type: "reasoning-delta"; id: string; text: string }
  | { type: "source"; source: unknown }
  | { type: "file"; file: { name: string; content: string } }
  | {
      type: "tool-call";
      toolCallId: string;
      toolName: string;
      input: unknown;
    }
  | {
      type: "tool-input-start";
      id: string;
      toolName: string;
    }
  | {
      type: "tool-input-delta";
      id: string;
      delta: string;
    }
  | { type: "tool-result"; toolCallId: string; result: unknown }
  | { type: "start-step" }
  | {
      type: "finish-step";
      response: object;
      usage: {
        inputTokens: number;
        outputTokens: number;
        totalTokens: number;
      };
      finishReason: string;
    }
  | {
      type: "finish";
      finishReason: string;
      totalUsage: {
        inputTokens: number;
        outputTokens: number;
        totalTokens: number;
      };
    }
  | { type: "error"; error: Error };

export interface VercelStreamConverterOptions {
  model: string;
}

/**
 * Converts a Vercel AI SDK stream event to OpenAI ChatCompletionChunk format.
 * Returns null for events that don't map to OpenAI chunks (like start-step, finish-step, etc.)
 */
export function convertVercelStreamPart(
  part: VercelStreamPart,
  options: VercelStreamConverterOptions,
): ChatCompletionChunk | null {
  const { model } = options;

  switch (part.type) {
    case "text-delta":
      return chatChunk({
        content: part.text,
        model,
      });

    case "reasoning-delta":
      // Reasoning content is emitted as a reasoning delta so downstream
      // consumers can distinguish it from regular text content.
      return chatChunkFromDelta({
        delta: {
          reasoning_content: part.text,
        } as ChatCompletionChunk.Choice["delta"],
        model,
      });

    case "tool-call":
      return chatChunkFromDelta({
        delta: {
          tool_calls: [
            {
              index: 0,
              id: part.toolCallId,
              type: "function" as const,
              function: {
                name: part.toolName,
                arguments: JSON.stringify(part.input),
              },
            },
          ],
        },
        model,
      });

    case "tool-input-delta":
      return chatChunkFromDelta({
        delta: {
          tool_calls: [
            {
              index: 0,
              function: {
                arguments: part.delta,
              },
            },
          ],
        },
        model,
      });

    case "finish":
      // Emit usage from finish event if available
      // The finish event DOES contain the final usage in most cases
      if (part.totalUsage) {
        const promptTokens =
          typeof part.totalUsage.inputTokens === "number"
            ? part.totalUsage.inputTokens
            : 0;
        const completionTokens =
          typeof part.totalUsage.outputTokens === "number"
            ? part.totalUsage.outputTokens
            : 0;
        const totalTokens =
          typeof part.totalUsage.totalTokens === "number"
            ? part.totalUsage.totalTokens
            : promptTokens + completionTokens;

        // Check for Anthropic-specific cache token details
        const cachedTokens = (part.totalUsage as any).cachedInputTokens;
        const promptTokensDetails =
          typeof cachedTokens === "number"
            ? {
                cached_tokens: cachedTokens,
                cache_read_tokens: cachedTokens,
                cache_write_tokens: 0,
              }
            : undefined;

        return usageChatChunk({
          model,
          usage: {
            prompt_tokens: promptTokens,
            completion_tokens: completionTokens,
            total_tokens: totalTokens,
            ...(promptTokensDetails
              ? { prompt_tokens_details: promptTokensDetails as any }
              : {}),
          },
        });
      }
      return null;

    case "error":
      // Errors should be thrown, not converted to chunks
      throw part.error;

    // Events that don't map to OpenAI chunks - return null to skip
    case "source":
    case "file":
    case "tool-input-start":
    case "tool-result":
    case "start-step":
    case "finish-step":
      return null;

    default:
      // Exhaustiveness check
      const _exhaustive: never = part;
      return null;
  }
}

/**
 * Async generator that converts Vercel AI SDK stream to OpenAI ChatCompletionChunk stream
 */
export async function* convertVercelStream(
  stream: AsyncIterable<VercelStreamPart>,
  options: VercelStreamConverterOptions,
): AsyncGenerator<ChatCompletionChunk, void, unknown> {
  for await (const part of stream) {
    const chunk = convertVercelStreamPart(part, options);
    if (chunk !== null) {
      yield chunk;
    }
  }
}
