+// src/vercelStreamConverter.ts
+import { chatChunk, chatChunkFromDelta, usageChatChunk } from "./util.js";
+function convertVercelStreamPart(part, options) {
+  const { model } = options;
+  switch (part.type) {
+    case "text-delta":
+      return chatChunk({
+        content: part.text,
+        model
+      });
+    case "reasoning-delta":
+      return chatChunkFromDelta({
+        delta: {
+          reasoning_content: part.text
+        },
+        model
+      });
+    case "tool-call":
+      return chatChunkFromDelta({
+        delta: {
+          tool_calls: [
+            {
+              index: 0,
+              id: part.toolCallId,
+              type: "function",
+              function: {
+                name: part.toolName,
+                arguments: JSON.stringify(part.input)
+              }
+            }
+          ]
+        },
+        model
+      });
+    case "tool-input-delta":
+      return chatChunkFromDelta({
+        delta: {
+          tool_calls: [
+            {
+              index: 0,
+              function: {
+                arguments: part.delta
+              }
+            }
+          ]
+        },
+        model
+      });
+    case "finish":
+      if (part.totalUsage) {
+        const promptTokens = typeof part.totalUsage.inputTokens === "number" ? part.totalUsage.inputTokens : 0;
+        const completionTokens = typeof part.totalUsage.outputTokens === "number" ? part.totalUsage.outputTokens : 0;
+        const totalTokens = typeof part.totalUsage.totalTokens === "number" ? part.totalUsage.totalTokens : promptTokens + completionTokens;
+        const cachedTokens = part.totalUsage.cachedInputTokens;
+        const promptTokensDetails = typeof cachedTokens === "number" ? {
+          cached_tokens: cachedTokens,
+          cache_read_tokens: cachedTokens,
+          cache_write_tokens: 0
+        } : void 0;
+        return usageChatChunk({
+          model,
+          usage: {
+            prompt_tokens: promptTokens,
+            completion_tokens: completionTokens,
+            total_tokens: totalTokens,
+            ...promptTokensDetails ? { prompt_tokens_details: promptTokensDetails } : {}
+          }
+        });
+      }
+      return null;
+    case "error":
+      throw part.error;
+    // Events that don't map to OpenAI chunks - return null to skip
+    case "source":
+    case "file":
+    case "tool-input-start":
+    case "tool-result":
+    case "start-step":
+    case "finish-step":
+      return null;
+    default:
+      const _exhaustive = part;
+      return null;
+  }
+}
+async function* convertVercelStream(stream, options) {
+  for await (const part of stream) {
+    const chunk = convertVercelStreamPart(part, options);
+    if (chunk !== null) {
+      yield chunk;
+    }
+  }
+}
+export {
+  convertVercelStream,
+  convertVercelStreamPart
+};
